# ABA 3: 📈 Eficiência RP
# ==========================================
with tabs[2]:
    st.subheader(f"📈 Eficiência da Recuperação Paralela (Acompanhamento dos Alunos) — {etapa_sel}")
    
    if is_comparativo:
        # Medição da quantidade de alunos atendidos e recuperados por turma
        df_ef_comp = df_filtered.groupby('turma').agg(
            al_rp_1=('em_rp_1', lambda x: df_filtered.loc[x.index[x], 'aluno'].nunique()),
            al_rp_2=('em_rp_2', lambda x: df_filtered.loc[x.index[x], 'aluno'].nunique())
        ).reset_index()
        
        # Alunos que reverteram 100% das notas em RP por turma
        al_rec_1 = df_filtered.groupby(['turma', 'aluno']).agg(tot_rp=('em_rp_1', 'sum'), perm=('permaneceu_1', 'sum')).reset_index()
        al_rec_1_tot = al_rec_1[(al_rec_1['tot_rp'] > 0) & (al_rec_1['perm'] == 0)].groupby('turma')['aluno'].nunique().reset_index().rename(columns={'aluno': 'recup_1'})
        
        al_rec_2 = df_filtered.groupby(['turma', 'aluno']).agg(tot_rp=('em_rp_2', 'sum'), perm=('permaneceu_2', 'sum')).reset_index()
        al_rec_2_tot = al_rec_2[(al_rec_2['tot_rp'] > 0) & (al_rec_2['perm'] == 0)].groupby('turma')['aluno'].nunique().reset_index().rename(columns={'aluno': 'recup_2'})
        
        df_ef_comp = pd.merge(df_ef_comp, al_rec_1_tot, on='turma', how='left').fillna(0)
        df_ef_comp = pd.merge(df_ef_comp, al_rec_2_tot, on='turma', how='left').fillna(0)
        
        df_ef_comp['tx_reversao_1'] = (df_ef_comp['recup_1'] / df_ef_comp['al_rp_1']) * 100
        df_ef_comp['tx_reversao_2'] = (df_ef_comp['recup_2'] / df_ef_comp['al_rp_2']) * 100
        df_ef_comp['var_tx'] = df_ef_comp['tx_reversao_2'] - df_ef_comp['tx_reversao_1']
        
        c_ef1, c_ef2 = st.columns([3, 2])
        
        with c_ef1:
            st.dataframe(
                df_ef_comp.rename(columns={
                    'turma': 'Turma',
                    'al_rp_1': 'Alunos RP (1ª)',
                    'recup_1': 'Recuperados Total (1ª)',
                    'tx_reversao_1': 'Taxa Reversão 1ª',
                    'al_rp_2': 'Alunos RP (2ª)',
                    'recup_2': 'Recuperados Total (2ª)',
                    'tx_reversao_2': 'Taxa Reversão 2ª',
                    'var_tx': 'Variação Taxa (%)'
                })[['Turma', 'Alunos RP (1ª)', 'Taxa Reversão 1ª', 'Alunos RP (2ª)', 'Taxa Reversão 2ª', 'Variação Taxa (%)']].style.format({
                    'Taxa Reversão 1ª': '{:.1f}%',
                    'Taxa Reversão 2ª': '{:.1f}%',
                    'Variação Taxa (%)': '{:+.1f}%'
                }),
                use_container_width=True
            )
            
        with c_ef2:
            fig_comp_ef = px.bar(
                df_ef_comp, x='turma', y=['tx_reversao_1', 'tx_reversao_2'],
                barmode='group',
                text_auto='.1f',
                title="Taxa de Reversão Total de Alunos em RP (%)",
                color_discrete_map={'tx_reversao_1': '#EA580C', 'tx_reversao_2': '#16A34A'}
            )
            fig_comp_ef.update_layout(xaxis_title="", yaxis_title="% Reversão Alunos")
            st.plotly_chart(fig_comp_ef, use_container_width=True)
    else:
        df_efic_turma = df_filtered.groupby('turma').agg(
            total_alunos=('aluno', 'nunique')
        ).reset_index()
        
        al_rp = df_filtered[df_filtered[col_em_rp]].groupby('turma')['aluno'].nunique().reset_index().rename(columns={'aluno': 'alunos_rp'})
        
        al_rec = df_filtered.groupby(['turma', 'aluno']).agg(tot_rp=(col_em_rp, 'sum'), perm=(col_perm, 'sum')).reset_index()
        al_rec_tot = al_rec[(al_rec['tot_rp'] > 0) & (al_rec['perm'] == 0)].groupby('turma')['aluno'].nunique().reset_index().rename(columns={'aluno': 'alunos_recuperados'})
        
        df_efic_turma = pd.merge(df_efic_turma, al_rp, on='turma', how='left').fillna(0)
        df_efic_turma = pd.merge(df_efic_turma, al_rec_tot, on='turma', how='left').fillna(0)
        
        df_efic_turma['pct_reversao'] = (df_efic_turma['alunos_recuperados'] / df_efic_turma['alunos_rp']) * 100
        df_efic_turma['pct_reversao'] = df_efic_turma['pct_reversao'].fillna(0.0)
        
        c_ef1, c_ef2 = st.columns([3, 2])
        
        with c_ef1:
            st.dataframe(
                df_efic_turma.rename(columns={
                    'turma': 'Turma',
                    'total_alunos': 'Total Alunos',
                    'alunos_rp': 'Alunos em RP',
                    'alunos_recuperados': 'Alunos Recuperados 100%',
                    'pct_reversao': '% Taxa Reversão Alunos'
                }).style.format({
                    '% Taxa Reversão Alunos': '{:.1f}%'
                }),
                use_container_width=True
            )
            
        with c_ef2:
            fig_reversao = px.bar(
                df_efic_turma, x='turma', y='pct_reversao',
                text_auto='.1f',
                title="% de Alunos que Reverteram RP por Turma",
                color='pct_reversao', color_continuous_scale='Greens'
            )
            fig_reversao.update_layout(showlegend=False, yaxis_title="% Reversão Alunos", xaxis_title="")
            st.plotly_chart(fig_reversao, use_container_width=True)

