    if is_comparativo:
        st_risco_1 = df_filtered.groupby(['aluno', 'turma']).agg(cnt=('abaixo5_1', 'sum'), med1=('final_1', 'mean')).reset_index()
        st_risco_2 = df_filtered.groupby(['aluno', 'turma']).agg(cnt=('abaixo5_2', 'sum'), med2=('final_2', 'mean')).reset_index()
        
        df_risk_comp = pd.merge(st_risco_1, st_risco_2, on=['aluno', 'turma'])
