        # Filtra alunos em risco na 1ª ou 2ª etapa
        df_risk_comp = df_risk_comp[(df_risk_comp['cnt_x'] >= 3) | (df_risk_comp['cnt_y'] >= 3)].sort_values(by=['cnt_y', 'cnt_x'], ascending=[False, False])
        
        if len(df_risk_comp) > 0:
            c_r1, c_r2, c_r3 = st.columns(3)
