            c_r1.metric("ALUNOS EM RISCO CRÍTICO", len(st_risco), "3+ matérias < 5,0")
            c_r2.metric("MAIOR Nº DE DISCIPLINAS CRÍTICAS", st_risco['disciplinas_abaixo5'].max(), "matérias < 5,0")
